export const CORE_KEYS = ["MOCK", "QA", "GK1", "GK2", "EN3"];
export const SEC_META = {
  MOCK: { name: "Maths Mock", icon: "🟣", color: "#c084fc" },
  QA:   { name: "Maths Topic", icon: "🧮", color: "#f59e0b" },
  GI:   { name: "Reasoning", icon: "🧠", color: "#6bd39a" },
  EN1:  { name: "English · Grammar", icon: "📘", color: "#8ab4f8" },
  EN2:  { name: "English · Practice", icon: "📘", color: "#8ab4f8" },
  EN3:  { name: "English · Vocab", icon: "🔤", color: "#8ab4f8" },
  GK1:  { name: "GK-1", icon: "🌍", color: "#ff8a7a" },
  GK2:  { name: "GK-2", icon: "🌍", color: "#ff8a7a" },
  ADV:  { name: "Advance Booster", icon: "⚡", color: "#f59e0b" },
};

const KEY = "cgl.rbe50";

function read() {
  if (typeof window === "undefined") return { startDate: null, done: {} };
  try {
    const v = JSON.parse(storeGet(KEY) || "{}");
    return { startDate: v.startDate || null, done: v.done || {} };
  } catch {
    return { startDate: null, done: {} };
  }
}
function write(v) {
  try { storeSet(KEY, JSON.stringify(v)); } catch { /* quota */ }
}

export function getRbe() { return read(); }
export function setStartDate(date) { const v = read(); v.startDate = date; write(v); return v; }
// id is "si-ii" (section-item) or "adv" for the day's Advance Booster test.
export function toggleItem(day, id) {
  const v = read();
  const d = v.done[day] || (v.done[day] = {});
  if (d[id]) delete d[id]; else d[id] = true;
  write(v);
  return v;
}

export function planFor(n) { return DAYS.find((d) => d.day === n) || null; }
// The one ADV test surfaced on a pre-day-38 day (sequential, so slipping days
// never re-serves what's already covered).
export function advFor(n) {
  if (n >= 38 || n < 1) return null;
  return ADV_POOL[(n - 1) % ADV_POOL.length] || null;
}

// Same dayKey()-based day number as the old planner: the day rolls over at the
// configured day-end (default 02:00), not midnight.
export function currentDayNum(state = read()) {
  if (!state.startDate) return 0;
  const [y1, m1, d1] = state.startDate.split("-").map(Number);
  const [y2, m2, d2] = dayKey().split("-").map(Number);
  return Math.round((Date.UTC(y2, m2 - 1, d2) - Date.UTC(y1, m1 - 1, d1)) / 864e5) + 1;
}

export function dayStats(state, n) {
  const p = planFor(n);
  if (!p) return { total: 0, done: 0, coreTotal: 0, coreDone: 0 };
  const done = state.done[n] || {};
  let total = 0, dn = 0, coreTotal = 0, coreDone = 0;
  p.secs.forEach((s, si) => {
    const core = CORE_KEYS.includes(s.k);
    s.items.forEach((_, ii) => {
      total++;
      if (core) coreTotal++;
      if (done[si + "-" + ii]) { dn++; if (core) coreDone++; }
    });
  });
  return { total, done: dn, coreTotal, coreDone };
}
export function dayCompletion(state, n) {
  const s = dayStats(state, n);
  return s.total ? s.done / s.total : 0;
}
// A day "counts" when its CORE sections are fully ticked.
export function coreComplete(state, n) {
  const s = dayStats(state, n);
  return s.coreTotal > 0 && s.coreDone >= s.coreTotal;
}
export function planStreak(state) {
  const cur = Math.min(currentDayNum(state), 50);
  let s = 0;
  if (cur >= 1 && coreComplete(state, cur)) s++;
  for (let i = cur - 1; i >= 1; i--) {
    if (coreComplete(state, i)) s++; else break;
  }
  return s;
}
